/* NewsLens: dependency-free text classifier, shared with Node tests. */
(function(root){
const tokens=t=>(t.toLowerCase().match(/[\p{L}\p{M}]{2,}/gu)||[]);
function parseCSV(s){let rows=[],row=[],v='',quoted=false;for(let i=0;i<s.length;i++){let c=s[i];if(c==='"'){if(quoted&&s[i+1]==='"'){v+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(v);v='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&s[i+1]==='\n')i++;row.push(v);if(row.some(x=>x.trim()))rows.push(row);row=[];v='';}else v+=c;}if(quoted)throw Error('Unclosed quote in CSV.');row.push(v);if(row.some(x=>x.trim()))rows.push(row);return rows;}
function dataset(s){const rows=parseCSV(s),head=(rows.shift()||[]).map(x=>x.replace(/^\uFEFF/,'').trim().toLowerCase()),ti=head.indexOf('text'),li=head.indexOf('label');if(ti<0||li<0)throw Error('CSV needs text and label columns.');if(rows.length>5000)throw Error('Maximum 5,000 rows.');const seen=new Map(),out=[];for(const r of rows){const text=(r[ti]||'').trim(),label=(r[li]||'').trim().toLowerCase();if(!['real','fake'].includes(label)||tokens(text).length<5)throw Error('Every row needs real/fake and at least 5 words of text.');const key=tokens(text).join(' ');if(seen.has(key)){if(seen.get(key)!==label)throw Error('Duplicate article has conflicting labels.');continue;}seen.set(key,label);out.push({text,label});}for(const c of ['real','fake'])if(out.filter(x=>x.label===c).length<10)throw Error('Use at least 10 unique articles for each class.');return out;}
function train(rows){const m={counts:{real:{},fake:{}},totals:{real:0,fake:0},docs:{real:0,fake:0},vocab:{}};for(const r of rows){m.docs[r.label]++;for(const t of tokens(r.text)){m.vocab[t]=1;m.counts[r.label][t]=(m.counts[r.label][t]||0)+1;m.totals[r.label]++;}}m.size=Object.keys(m.vocab).length;return m;}
function predict(m,text){const ts=tokens(text).filter(t=>m.vocab[t]),total=m.docs.real+m.docs.fake;let scores={};for(const c of ['real','fake']){scores[c]=Math.log(m.docs[c]/total);for(const t of ts)scores[c]+=Math.log(((m.counts[c][t]||0)+1)/(m.totals[c]+m.size));}return {label:ts.length?(scores.fake>scores.real?'fake':'real'):'unknown',known:ts.length,unique:[...new Set(ts)].length};}
function evaluate(rows){let seed=42;const rand=()=>{seed=(1664525*seed+1013904223)>>>0;return seed/4294967296;};let training=[],test=[];for(const c of ['real','fake']){let a=rows.filter(r=>r.label===c);for(let i=a.length-1;i>0;i--){const j=Math.floor(rand()*(i+1));[a[i],a[j]]=[a[j],a[i]];}let n=Math.max(1,Math.floor(a.length*.2));test.push(...a.slice(0,n));training.push(...a.slice(n));}const model=train(training);let correct=0,tp=0,fp=0,fn=0;for(const r of test){let p=predict(model,r.text).label;correct+=p===r.label?1:0;tp+=p==='fake'&&r.label==='fake'?1:0;fp+=p==='fake'&&r.label==='real'?1:0;fn+=p!=='fake'&&r.label==='fake'?1:0;}return {model,stats:{train:training.length,test:test.length,accuracy:correct/test.length,precision:tp+fp?tp/(tp+fp):null,recall:tp+fn?tp/(tp+fn):null}};}
function signals(text){const checks=[['Urgent sharing request',/share (?:this|it)|forward (?:this|it)|before (?:it|they).*delet|send (?:this|it) to/i,'Pressure to share can discourage checking.'],['Sensational wording',/shocking|unbelievable|you won.t believe|secret cure|miracle|100% guaranteed|they don.t want you to know/i,'Strong emotional language deserves a closer look.'],['Heavy emphasis',/!{2,}|\b[A-Z]{5,}\b/,'Repeated exclamation marks or all-caps wording are style cues, not proof.'],['Vague attribution',/scientists say|experts say|sources say|a friend.*said|doctors say/i,'Look for named people and the original evidence.']];return checks.filter(x=>x[1].test(text)).map(x=>({title:x[0],detail:x[2]}));}
const api={tokens,parseCSV,dataset,train,predict,evaluate,signals};if(typeof module!=='undefined')module.exports=api;else root.NewsEngine=api;
})(typeof window==='undefined'?globalThis:window);
